    [DatabaseFact]
    public async Task Every_tenant_table_of_the_schema_is_under_its_security_policy()
    {
        using var scope = fixture.ScopeFor(null);
        var db = Db(scope);
        var expected = db.Model.GetEntityTypes().Where(e => typeof(ITenantScoped).IsAssignableFrom(e.ClrType)).Select(e => e.GetTableName()!).ToHashSet();
        Assert.Equal(108, expected.Count);
        var covered = await db.Database.SqlQueryRaw<string>($"""
            SELECT OBJECT_NAME(p.target_object_id) AS [Value]
            FROM sys.security_predicates p JOIN sys.security_policies s ON s.object_id = p.object_id
            WHERE s.name = 'tenant_policy_{S}' AND p.predicate_type_desc = 'FILTER'
            """).ToListAsync();
        Assert.Equal(expected.OrderBy(x => x), covered.OrderBy(x => x));
        Assert.Subset(covered.ToHashSet(), new HashSet<string>
        {
            "claim", "claim_line", "claim_evidence", "recovery_claim", "rma", "rma_line", "return_receipt", "return_reason",
            "refurbishment_work_order", "refurbishment_operation", "refurbishment_part", "refurbishment_labour", "refurbishment_cost", "coverage_decision",
            "certificate_template", "certificate_template_version", "certificate_instance", "certificate_trigger", "certificate_signature", "reprint_log",
            "tenant_asset",
            "certificate_run", "certificate_run_unit",
            "label_template", "label_template_version", "print_job",
            "region_group", "jurisdiction_rule", "rule_pack", "rule_pack_rule",
            "number_series_setting",
            "ledger_base_order_ref",
            "ledger_base_order_backfill_checkpoint",
            "rma_stage_counter",
            "import_job", "import_row_result", "column_mapping", "three_pl_feed_message",
            "import_file_download_audit",
            "customer_assertion", "disclosure_policy", "customer_reconciliation", "customer_reconciliation_row",
            "portal_registration",
            "unit_cover_deviation", "unit_cover_deviation_change", "unit_cover_deviation_value", "cover_deviation_backfill_checkpoint",
            "claim_cause", "policy_cover_item", "policy_cover_item_cause",
            "mail_template", "mail_template_version", "mail_template_default", "customer_mail_message",
        });
        var blocks = await db.Database.SqlQueryRaw<int>($"SELECT COUNT(*) AS [Value] FROM sys.security_predicates p JOIN sys.security_policies s ON s.object_id = p.object_id WHERE s.name = 'tenant_policy_{S}' AND p.predicate_type_desc = 'BLOCK'").SingleAsync();
        Assert.Equal(expected.Count * 2, blocks);
        Assert.Empty(db.ValidateTenantKeyConventions());
    }

