    [DatabaseFact]
    public async Task Ledger_tables_are_monthly_partitioned_with_every_index_aligned()
    {
        using var scope = fixture.ScopeFor(null);
        var db = Db(scope);
        // Initial creates 2024-01 .. 2027-12 monthly; the lifecycle tests may add boundaries ahead and merge 2024-01 away.
        var boundaries = await db.Database.SqlQueryRaw<DateTime>($"SELECT CAST(v.value AS datetime2(3)) AS [Value] FROM sys.partition_range_values v JOIN sys.partition_functions f ON f.function_id = v.function_id WHERE f.name = '{SerialisationDbContext.PartitionFunction}' ORDER BY v.boundary_id").ToListAsync();
        Assert.True(boundaries.Count >= 47, $"expected at least 47 monthly boundaries, found {boundaries.Count}");
        Assert.True(boundaries[0] <= new DateTime(2024, 2, 1));
        Assert.True(boundaries[^1] >= new DateTime(2027, 12, 1));
        Assert.All(boundaries, b => Assert.Equal(1, b.Day));
        var rangeRight = await db.Database.SqlQueryRaw<bool>($"SELECT boundary_value_on_right AS [Value] FROM sys.partition_functions WHERE name = '{SerialisationDbContext.PartitionFunction}'").SingleAsync();
        Assert.True(rangeRight);
        foreach (var table in new[] { "unit_event", "unit_event_archive", "unit_event_archive_stage" })
        {
            // Every index must live on the partition scheme so a cold month remains switch-compatible.
            var indexes = await db.Database.SqlQueryRaw<string>($"""
                SELECT CONCAT(i.name, '|', ISNULL(ps.name, 'NOT PARTITIONED'), '|', ISNULL(c.name, '')) AS [Value]
                FROM sys.indexes i
                LEFT JOIN sys.partition_schemes ps ON ps.data_space_id = i.data_space_id
                LEFT JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.partition_ordinal = 1
                LEFT JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
                WHERE i.object_id = OBJECT_ID('{S}.{table}') AND i.index_id > 0
                """).ToListAsync();
            Assert.Equal(5, indexes.Count); // plus document (P1-T21) and merged-from (P3-T09)
            Assert.All(indexes, x => Assert.EndsWith($"|{SerialisationDbContext.PartitionScheme}|event_time", x));
            Assert.Contains(indexes, x => x.StartsWith($"pk_{table}|", StringComparison.Ordinal));
            Assert.Contains(indexes, x => x.StartsWith($"ux_{table}_tenant_id_idempotency_key_event_time|", StringComparison.Ordinal));
            Assert.Contains(indexes, x => x.StartsWith($"ix_{table}_tenant_id_unit_id_event_time|", StringComparison.Ordinal));
        }

        var seqCache = await db.Database.SqlQueryRaw<int>($"SELECT CAST(cache_size AS int) AS [Value] FROM sys.sequences WHERE name = '{SerialisationDbContext.EventSequence}' AND schema_id = SCHEMA_ID('{S}')").SingleAsync();
        Assert.Equal(1000, seqCache);
    }

    [DatabaseFact]
    public async Task Base_order_lookup_is_sparse_and_its_migration_never_alters_the_ledger_tables()
    {
        using var scope = fixture.ScopeFor(null);
        var db = Db(scope);
        var columns = await db.Database.SqlQueryRaw<string>($"""
            SELECT CONCAT(OBJECT_NAME(object_id), '.', name) AS [Value]
            FROM sys.columns
            WHERE object_id IN (OBJECT_ID('{S}.unit_event'), OBJECT_ID('{S}.unit_event_archive'),
                                OBJECT_ID('{S}.unit_event_archive_stage'))
              AND name LIKE 'base_document%'
            """).ToListAsync();
        Assert.Empty(columns);

        var lookupIndex = await db.Database.SqlQueryRaw<string>($"""
            SELECT name AS [Value] FROM sys.indexes
            WHERE object_id = OBJECT_ID('{S}.ledger_base_order_ref') AND name LIKE 'ix_ledger_base_order_ref%'
            """).SingleAsync();
        Assert.Equal("ix_ledger_base_order_ref_tenant_id_base_document_type_base_document_id_base_document_line", lookupIndex);

        var script = db.GetService<IMigrator>().GenerateScript(
            "20261018145354_P6PerformanceReadPaths", "20261018164330_P6PerfLedgerReadShapes");
        Assert.DoesNotContain("ALTER TABLE [serialisation].[unit_event]", script, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("CREATE TABLE [serialisation].[ledger_base_order_ref]", script, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("CREATE TABLE [serialisation].[ledger_base_order_backfill_checkpoint]", script, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("JSON_VALUE", script, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("INSERT INTO [serialisation].[ledger_base_order_ref]", script, StringComparison.OrdinalIgnoreCase);
    }

    [DatabaseFact]
    public void Policy_row_version_upgrade_unbinds_versioning_and_the_tenant_policy_before_adding_the_column()
    {
        // Found 2026-10-20 upgrading a database with policy history: a rowversion column cannot be added to a
        // system-versioned table, and the schema-bound tenant policy blocks the ALTER. A fresh database never shows it.
        using var scope = fixture.ScopeFor(null);
        var script = Db(scope).GetService<IMigrator>().GenerateScript("20261017203758_P5Refurb", "20261018063446_P6DocVersion");

        int At(string sql)
        {
            var index = script.IndexOf(sql, StringComparison.OrdinalIgnoreCase);
            Assert.True(index >= 0, $"Missing: {sql}");
            return index;
        }

        var policyOff = At("WITH (STATE = OFF)");
        var versioningOff = At("ALTER TABLE [serialisation].[warranty_policy_version] SET (SYSTEM_VERSIONING = OFF)");
        var history = At("ALTER TABLE [serialisation].[warranty_policy_version_history] ADD [row_version] rowversion NOT NULL");
        var current = At("ALTER TABLE [serialisation].[warranty_policy_version] ADD [row_version] rowversion NOT NULL");
        var versioningOn = At("ALTER TABLE [serialisation].[warranty_policy_version] SET (SYSTEM_VERSIONING = ON");
        var policyOn = At("WITH (STATE = ON)");
        Assert.True(policyOff < versioningOff && versioningOff < history && history < current && current < versioningOn
            && versioningOn < policyOn, "The row_version upgrade runs out of order.");
    }

