    [DatabaseFact]
    public async Task Identity_rule_1_one_open_identifier_per_scope_and_value_across_units()
    {
        var tenant = await fixture.NewTenantAsync("s");
        var itemA = Guid.NewGuid();
        var first = await NewUnitAsync(tenant, itemA, "2506-493445");

        // Same string, same item: refused while the first is open.
        using (var scope = fixture.ScopeFor(tenant))
        {
            var db = Db(scope);
            var second = NewUnit(tenant);
            db.Units.Add(second);
            db.Identifiers.Add(NewIdentifier(tenant, second.UnitId, IdentifierType.InternalSerial, itemA.ToString("N"), "2506-493445"));
            var ex = await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync());
            Assert.Contains("ux_unit_identifier_tenant_id_scheme_scope_key_normalised_value", ex.InnerException!.Message, StringComparison.Ordinal);
        }

        // Same string on another item is legal (case 1): the scope key differs.
        using (var scope = fixture.ScopeFor(tenant))
        {
            var db = Db(scope);
            var other = NewUnit(tenant);
            db.Units.Add(other);
            db.Identifiers.Add(NewIdentifier(tenant, other.UnitId, IdentifierType.VendorSerial, Guid.NewGuid().ToString("N"), "2506-493445"));
            await db.SaveChangesAsync();
        }

        // Correction closes the old row; the string becomes free again (Identity rule 5).
        using (var scope = fixture.ScopeFor(tenant))
        {
            var db = Db(scope);
            var open = await db.Identifiers.SingleAsync(i => i.UnitId == first && i.ValidTo == null);
            open.ValidTo = DateTime.UtcNow;
            open.CorrectionReason = "mistyped";
            var replacement = NewIdentifier(tenant, first, IdentifierType.InternalSerial, itemA.ToString("N"), "2506-493454");
            open.SupersededByIdentifierId = replacement.IdentifierId;
            db.Identifiers.Add(replacement);
            await db.SaveChangesAsync();
            var reuse = NewUnit(tenant);
            db.Units.Add(reuse);
            db.Identifiers.Add(NewIdentifier(tenant, reuse.UnitId, IdentifierType.InternalSerial, itemA.ToString("N"), "2506-493445"));
            await db.SaveChangesAsync();
            Assert.Equal(2, await db.Identifiers.CountAsync(i => i.NormalisedValue == "2506493445" && i.Scheme == IdentifierScheme.Internal));
        }
    }

