    }

    [DatabaseFact]
    public async Task Events_land_in_the_partition_of_their_business_time_and_stay_tenant_private()
    {
        var a = await fixture.NewTenantAsync("a");
        var b = await fixture.NewTenantAsync("b");
        var unit = await NewUnitAsync(a, Guid.NewGuid(), "EV-" + Guid.NewGuid().ToString("N")[..8]);
        var businessTime = new DateTime(2026, 9, 1, 14, 12, 0, DateTimeKind.Utc);
        var migrated = new DateTime(2019, 3, 6, 8, 2, 0, DateTimeKind.Utc);
        using (var scope = fixture.ScopeFor(a))
        {
            var db = Db(scope);
            // NEXT VALUE FOR cannot sit in a derived table (which SqlQueryRaw builds), so read it through the connection.
            await db.Database.OpenConnectionAsync();
            await using var command = db.Database.GetDbConnection().CreateCommand();
            command.CommandText = $"SELECT NEXT VALUE FOR [{S}].[{SerialisationDbContext.EventSequence}]";
            var seq = (long)(await command.ExecuteScalarAsync())!;
            db.Events.Add(NewEvent(a, unit, businessTime, seq, UnitEventType.Shipped, "k-" + Guid.NewGuid().ToString("N")));
            db.Events.Add(NewEvent(a, unit, migrated, seq + 1, UnitEventType.Commissioned, "k-" + Guid.NewGuid().ToString("N")));
            db.Current.Add(new UnitCurrent { TenantId = a, UnitId = unit, ItemId = Guid.NewGuid(), LifecycleStatus = LifecycleStatus.Released, Disposition = UnitDisposition.InTransit, LastEventSeq = seq, LastEventTime = businessTime });
            await db.SaveChangesAsync();

            var partitions = await db.Database.SqlQueryRaw<int>($"SELECT $PARTITION.{SerialisationDbContext.PartitionFunction}(event_time) AS [Value] FROM [{S}].[unit_event] WHERE unit_id = '{unit}' ORDER BY event_time").ToListAsync();
            Assert.Equal(2, partitions.Count);
            Assert.Equal(1, partitions[0]); // before the first boundary: the cold catch-all partition
            // RANGE RIGHT: partition n+1 holds [boundary n, boundary n+1), so the partition of a time is the count of boundaries at or before it, plus one.
            var boundariesBefore = await db.Database.SqlQueryRaw<int>($"SELECT COUNT(*) AS [Value] FROM sys.partition_range_values v JOIN sys.partition_functions f ON f.function_id = v.function_id WHERE f.name = '{SerialisationDbContext.PartitionFunction}' AND CAST(v.value AS datetime2(3)) <= '2026-09-01'").SingleAsync();
            Assert.Equal(boundariesBefore + 1, partitions[1]);

            // Idempotency: the same key at the same business time is refused by the aligned unique index.
            db.Events.Add(NewEvent(a, unit, businessTime, seq + 2, UnitEventType.Shipped, (await db.Events.FirstAsync(e => e.UnitId == unit && e.EventTime == businessTime)).IdempotencyKey));
            var ex = await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync());
            Assert.IsType<SqlException>(ex.InnerException);
        }

        using (var scope = fixture.ScopeFor(b))
        {
            var db = Db(scope);
            Assert.Empty(await db.Events.Where(e => e.UnitId == unit).ToListAsync());
            Assert.Equal(0, await db.Database.SqlQueryRaw<int>($"SELECT COUNT(*) AS [Value] FROM [{S}].[unit_event] WHERE unit_id = '{unit}'").SingleAsync());
            Assert.Null(await db.Current.FindAsync(b, unit));
        }
    }

    private static Unit NewUnit(TenantId tenant) => new()
    {
        TenantId = tenant,
        UnitId = TimeOrderedId.New(),
        LifecycleStatus = LifecycleStatus.PreRelease,
        Origin = UnitOrigin.Manufactured,
        SerialisationPoint = SerialisationPoint.ProductionRelease,
        RetentionClass = "standard_10y",
        CreatedAt = DateTime.UtcNow,
        CreatedEventId = TimeOrderedId.New(),
        CreatedEventTime = DateTime.UtcNow,
    };

    private static UnitIdentifier NewIdentifier(TenantId tenant, Guid unit, string type, string scope, string raw) => new()
    {
        TenantId = tenant,
        IdentifierId = TimeOrderedId.New(),
        UnitId = unit,
        Type = type,
        Scheme = type == IdentifierType.VendorSerial ? IdentifierScheme.Oem : IdentifierScheme.Internal,
        ScopeKey = scope,
        RawValue = raw,
        NormalisedValue = raw.Replace("-", "", StringComparison.Ordinal).ToUpperInvariant(),
        ValidFrom = DateTime.UtcNow,
        ActorRef = "test",
        RecordedTime = DateTime.UtcNow,
        EventId = TimeOrderedId.New(),
    };

    private static CustodyEpisode NewEpisode(TenantId tenant, Guid unit, string kind) => new()
    {
        TenantId = tenant,
        EpisodeId = TimeOrderedId.New(),
        UnitId = unit,
        Kind = kind,
        PartyType = PartyType.Us,
        LocationKind = kind == EpisodeKind.Custody ? LocationKind.Warehouse : null,
        Reason = EpisodeReason.Production,
        Source = EpisodeSource.Receipt,
        Confidence = Confidence.High,
        ValidFrom = DateTime.UtcNow,
        OpeningEventId = TimeOrderedId.New(),
    };

    private static UnitEvent NewEvent(TenantId tenant, Guid unit, DateTime at, long seq, string type, string key) => new()
    {
        TenantId = tenant,
        EventTime = at,
        EventId = TimeOrderedId.New(at),
        UnitId = unit,
        Seq = seq,
        EventType = type,
        LegalEntityId = Guid.NewGuid(),
        ActorRef = "test",
        RecordedTime = DateTime.UtcNow,
        IdempotencyKey = key,
    };

    private async Task<Guid> NewUnitAsync(TenantId tenant, Guid item, string serial)
    {
        using var scope = fixture.ScopeFor(tenant);
        var db = Db(scope);
        var unit = NewUnit(tenant);
        db.Units.Add(unit);
        db.Identifiers.Add(NewIdentifier(tenant, unit.UnitId, IdentifierType.InternalSerial, item.ToString("N"), serial));
        await db.SaveChangesAsync();
        return unit.UnitId;
    }
}
